version = '2.3.0'
group = 'net.hawthorn.dndsheets'
archivesBaseName = 'vttminerpg'

java.toolchain.languageVersion = JavaLanguageVersion.of(17)

minecraft {
    mappings channel: 'parchment', version: '2023.09.03-1.20.1'


    copyIdeResources = true

    runs {
        client {
            workingDirectory project.file('runClient')

            property 'forge.logging.markers', 'REGISTRIES'
            property 'forge.logging.console.level', 'debug'

            mods {
                dndsheets {
                    source sourceSets.main
                }
            }
        }

        // In-GAME tests, with nobody watching: starts a server, places the arena, runs each
        // @GameTest and exits. The exit code is the number of tests that failed, so it works as-is
        // in CI or in a hook.
        //
        //     ./gradlew runGameTestServer
        //
        // It is the other half of invariant 11: JsonContentSelfTest covers everything that can be tested
        // standing up, and this covers what can't —a real entity, with its NBT, in a real world—, which until
        // now was only checked by playing.
        gameTestServer {
            workingDirectory project.file('runGameTest')

            property 'forge.logging.console.level', 'info'

            mods {
                dndsheets {
                    source sourceSets.main
                }
            }
        }

        server {
            workingDirectory project.file('runServer')

            property 'forge.logging.markers', 'REGISTRIES'
            property 'forge.logging.console.level', 'debug'

            mods {
                dndsheets {
                    source sourceSets.main
                }
            }
        }
    }
}

// --- How this is tested, which took five startups to work out ---
//
// The development client (runClient) CANNOT load production mods that mixin into vanilla
// classes. They were tried one by one and all fail, each costing a startup: Oculus, Patchouli,
// LionfishAPI, Curios and Citadel. Always the same reason: the mod references SRG names (f_19803_,
// m_8097_, m_91087_) and this environment runs with parchment mappings, where those names don't exist.
// Passing the jar through fg.deobf fixes its bytecode but not its mixins; enabling mixin.env.remapRefMap
// fixes the deobfuscated jar's mixins and breaks everyone else's. No combination works.
//
// So runClient/mods stays EMPTY: runClient is for developing this mod, and for that it is
// plenty. The integrations (appearance packs, Patchouli, Curios) are tested where they will be used:
//
//     ./gradlew build   ->   build/libs/vttminerpg-2.3.0.jar   ->   normal 1.20.1 install
//
// There everything is production and everything matches.
// tools/preflight_mods.py is still useful for the real install: it tells you what's missing before starting.

configurations {
    shade
    implementation.extendsFrom shade
}

repositories {
    // Curios API. SOFT dependency: compileOnly only, never packaged or required at runtime — the
    // mod starts and works the same without Curios installed (see CuriosCompat and the optional entry in
    // mods.toml). If this maven were down, the only thing that breaks is compiling, not the published mod.
    maven { url = "https://maven.theillusivec4.top/" }

    // Patchouli. The same kind of dependency as Curios: SOFT and compileOnly only. It is the standard mod
    // for in-game manuals, and this mod's Guide is exactly that. Without it installed, the
    // Guide still opens as the usual written book (see PatchouliCompat).
    maven { url = "https://maven.blamejared.com" }

    // Jade. The same kind of dependency as Curios and Patchouli: SOFT and compileOnly only. Jade doesn't publish
    // a maven of its own, so it is taken from CurseMaven. The group filter is what keeps this repo
    // from getting in the middle of resolving Forge or the project's libraries.
    maven {
        url = "https://cursemaven.com"
        content { includeGroup "curse.maven" }
    }

    // Pehkui. Another SOFT dependency (see PehkuiCompat). It is taken from Modrinth's maven, just like Origins
    // in species/build.gradle, and with the same group filter.
    maven {
        url = "https://api.modrinth.com/maven"
        content { includeGroup "maven.modrinth" }
    }
}

dependencies {
    // 47.4.22 and not 47.2.0: several mods used to test the integration (FTB Library, Easy NPC,
    // Carry On Extend) require 47.3+ or 47.4+, and with 47.2.0 the development client doesn't even start. It is the
    // same 1.20.1; mods.toml asks for no Forge version, so this doesn't change what the published
    // mod requires, only what it is compiled and tested with.
    minecraft 'net.minecraftforge:forge:1.20.1-47.4.22'
    // https://mvnrepository.com/artifact/io.github.tfriedrichs/dicebot
    minecraftLibrary 'io.github.tfriedrichs:dicebot:1.0.0'
    shade 'io.github.tfriedrichs:dicebot:1.0.0'

    // The "api" classifier and not the full jar: it is all that is needed to compile against Curios,
    // and it makes clear that its implementation is not depended on. An EARLY 5.x version is pinned on
    // purpose: the two methods that are used (CuriosApi.getCuriosInventory and getEquippedCurios) have existed
    // from the start, and compiling against the oldest is what makes the mod work with
    // whatever Curios the user has installed, not just the latest.
    compileOnly fg.deobf("top.theillusivec4.curios:curios-forge:5.4.7+1.20.1:api")

    // Pehkui 3.7.6, the OLDEST 1.20.1 published. The same criterion as Curios and Jade: the only thing that is
    // called (ScaleTypes.BASE.getScaleData().setScale/setTargetScale) has existed for many versions, and
    // compiling against the oldest is what makes any Pehkui the player has installed work.
    // t5W7Jfwy = the project; rUlbXz1h = that version.
    compileOnly fg.deobf("maven.modrinth:t5W7Jfwy:rUlbXz1h")

    // Jade 11.8.0, the OLDEST 1.20.1 that already has the current shape of the plugin API. The same criterion
    // as Curios and for the same reason: compiling against the oldest is what makes the mod
    // work with whatever Jade the player has installed, not just the latest. fg.deobf is needed because
    // the signatures of Jade's API name vanilla types (Entity, CompoundTag) and the published jar
    // ships them with SRG names.
    compileOnly fg.deobf("curse.maven:jade-324717:5072729")

    // JEI, SOFT and compileOnly: only the api jar, to let items be dragged from JEI's list into the content
    // forms (see compat/DndJeiPlugin). JEI finds the plugin by annotation; without JEI nothing here loads.
    compileOnly fg.deobf("mezz.jei:jei-1.20.1-common-api:15.20.0.106")
    compileOnly fg.deobf("mezz.jei:jei-1.20.1-forge-api:15.20.0.106")

    // Only the "api" artifact, which is all that is touched: PatchouliAPI.get().
    compileOnly fg.deobf("vazkii.patchouli:Patchouli:1.20.1-85-FORGE:api")

    // The full jar is NOT added as runtimeOnly. Tested, and the result is the same dead end as
    // with Curios, just one step further: put by hand in runClient/mods, Patchouli dies on
    // startup calling Minecraft.m_91087_() (the SRG name of getInstance) from its
    // BookCrashHandler; passed through fg.deobf, that call is fixed but its mixins fail, and
    // enabling mixin.env.remapRefMap to fix them breaks the mixins of any other production mod with
    // mixins loaded in the same client —Citadel the first one when it was tried—.
    // A development client cannot have deobfuscated mods and production mods with
    // mixins at the same time, and that is why runClient/mods stays empty (see above).
    //
    // So the Patchouli Guide is tested in a normal install with the built jar. What
    // is checked here is its structure: checkPatchouliBook requires every page of the Guide to be
    // in exactly one entry of the book, in both directions.

    // The full jar is NOT added as runtimeOnly, even though it would be handy for testing the integration:
    // Curios is published with its mixins referencing SRG names (f_19803_), and runClient runs with
    // parchment mappings, where that name doesn't exist. The result is that the development client doesn't
    // start — tested with 5.14.1 and with 5.4.7, so it is not version drift but the environment's
    // remapping. Making it work would require configuring mixin refmap remapping, and the only thing it
    // would buy is being able to test Curios locally: the integration itself is structurally isolated
    // (see CuriosCompat) and is verified with javap, not by running it. To really test it, a
    // real install, not a development environment.
}

// The manifest is NOT decoration: mods.toml declares version="${file.jarVersion}", and that marker is
// resolved by Forge reading Implementation-Version from HERE. Without this line, the mod announces itself in-game
// with the literal text "${file.jarVersion}". It goes in both jars because the one that is published is the shadow.
// The value is captured HERE and not inside the closure: inside manifest{} the delegate is the Manifest, not
// the task, so archiveVersion doesn't resolve — it fails when evaluating the script, not when packaging.
def modVersion = project.version.toString()
def modManifest = {
    attributes(['Implementation-Version': modVersion])
}

jar {
    archiveClassifier = 'slim'
    manifest modManifest
}

shadowJar {
    archiveClassifier = ''
    configurations = [project.configurations.shade]
    relocate 'io.github.tfriedrichs.dicebot', "${project.group}.relocated.dicebot"
    manifest modManifest
