"""Read-only survey: Sketchfab models in Minecraft/Blockbench style, downloadable, CC0 or CC-BY, per archetype."""
import json, sys, time, urllib.parse, urllib.request

TERMS = {
    'dragon': 'dragon', 'goblinoid': 'goblin', 'brute': 'orc', 'giant': 'giant ogre', 'reptilian': 'kobold lizardman',
    'demon': 'demon devil', 'undead': 'zombie ghoul mummy', 'golem': 'golem', 'beast': 'wolf', 'cat': 'lion tiger',
    'reptile': 'crocodile lizard', 'serpent': 'snake serpent', 'spider': 'spider', 'ooze': 'slime ooze',
    'elemental': 'elemental', 'bird': 'eagle hawk owl', 'shark': 'shark', 'bear': 'bear', 'horse': 'horse',
    'skeleton': 'skeleton', 'griffon': 'griffin', 'beholder': 'beholder',
}
STYLE = ['blockbench', 'minecraft']
LICENSES = ['cc0', 'by']


def get(url):
    for _ in range(3):
        try:
            with urllib.request.urlopen(urllib.request.Request(url, headers={'User-Agent': 'dndsheets-survey'}), timeout=20) as r:
                return json.load(r)
        except Exception as e:
            time.sleep(2)
    return {'results': []}


seen, rows = set(), []
for arch, term in TERMS.items():
    for style in STYLE:
        for lic in LICENSES:
            q = urllib.parse.urlencode({'type': 'models', 'q': '%s %s' % (style, term), 'downloadable': 'true',
                                        'license': lic, 'count': 24, 'sort_by': '-viewCount'})
            for m in get('https://api.sketchfab.com/v3/search?' + q).get('results', []):
                if m['uid'] in seen:
                    continue
                seen.add(m['uid'])
                tags = ' '.join(t['name'] for t in m.get('tags', []))
