                                 likes=m['likeCount'], license=m['license']['label'] if m.get('license') else '?',
                                 faces=m['faceCount'], anims=m['animationCount'], user=m['user']['username'],
                                 blocky=('blockbench' in tags or 'minecraft' in tags or 'voxel' in tags or 'blockbench' in m['name'].lower() or 'minecraft' in m['name'].lower())))
            time.sleep(0.3)
json.dump(rows, open(sys.argv[1], 'w'), indent=1)
print(len(rows))

