def run_create_mesh(mesh, sources):
    for java in sources:
        body = method_body(java, 'createMesh')
        if body:
            return apply(mesh, body, sources[sources.index(java) + 1:])
    raise ValueError('createMesh() not found in the class or its listed bases')


