def remove_trials():
    for f in os.listdir(os.path.join(A, 'geo', 'entity')):
        if f.startswith('tri_'):
            n = f[:-len('.geo.json')]
            os.remove(os.path.join(A, 'geo', 'entity', f))
            p = os.path.join(A, 'animations', 'entity', n + '.animation.json')
            if os.path.exists(p):
                os.remove(p)
            shutil.rmtree(os.path.join(A, 'textures', 'entity', n), ignore_errors=True)
    c = os.path.join(A, 'CREDITS.txt')
    lines = [l for l in open(c, encoding='utf-8').read().splitlines() if not re.match(r'(textures/entity/tri_|geo/entity/tri_)', l)]
    open(c, 'w', encoding='utf-8', newline='\n').write('\n'.join(lines) + '\n')
    s = os.path.join(A, 'creatures', 'scales.json')
    sc = {k: v for k, v in json.load(open(s)).items() if not k.startswith('tri_')}
    json.dump(sc, open(s, 'w', newline='\n'), indent=1)


def main(names):
    tiles = []
    for name in names:
        x = find(WANT[name])
        if not x:
            print(name, 'not in survey'); continue
        uid = x['url'].rstrip('/').split('-')[-1]
        try:
            fresh = not os.path.exists(os.path.join(gltf.CACHE, 'tri_' + name, 'scene.gltf'))
            gltf.install('tri_' + name, dict(uid=uid, dir='tri_' + name))
            if fresh:
                time.sleep(8)
            m = render.Model('tri_' + name)
            img = render.label(render.frame(m, m.texture(next(iter(m.palettes))), 'three-quarter', size=(220, 220)), '%s %dv' % (name, x['views']))
            tiles.append(img)
        except Exception as e:
            print(name, 'FAILED', type(e).__name__, str(e)[:120])
    if tiles:
        render.grid(tiles, 5).save(os.path.join(REPO, 'tools', 'blockbench', 'out', 'review', 'triage.png'))


if __name__ == '__main__':
    if sys.argv[1:] == ['--clean']:
        remove_trials()
    else:
        main(sys.argv[1:] or list(WANT))

